    flag: "webhooks",
  },
  {
    key: "settings.export",
    label: "Export",
    segment: "export",
    action: "activity:export",
    flag: "csv_export",
  },
];

/**
 * The resource a nav-level permission question is asked about. Nav items are
 * asked "could this actor do this at all in this org?", so the resource is
 * always the actor's own org, shaped for the action's resource kind.
 */
function navResource(action: PermissionAction, actor: Actor): PermissionResource {
  const [domain] = action.split(":");
  switch (domain) {
    case "org":
      return action === "org:manage_billing"
        ? { kind: "billing", orgId: actor.orgId }
        : { kind: "organization", orgId: actor.orgId };
    case "activity":
      return { kind: "activity", orgId: actor.orgId };
    case "notification":
      return { kind: "notification", orgId: actor.orgId, recipientId: actor.userId };
    case "webhook":
      return { kind: "webhook", orgId: actor.orgId, webhookId: null };
    default:
      // member / project / issue / comment nav entries are org-wide questions.
      return { kind: "organization", orgId: actor.orgId };
  }
}

/**
 * A snapshot is normally complete, but a client provider may be holding one
 * serialised before a flag existed. Fall back to evaluating the flag directly
 * with the conservative context we can build from the actor alone.
 */
function flagAllows(
  flag: FeatureFlagKey,
  actor: Actor,
  flags: FeatureFlagSnapshot,
): boolean {
  const snapshotted: boolean | undefined = flags[flag];
  if (typeof snapshotted === "boolean") return snapshotted;
  return isEnabled(flag, {
    orgId: actor.orgId,
    userId: actor.userId,
    plan: "free",
    role: actor.role,
  });
}

/**
 * Filters a nav tree down to what `actor` may see, recursing into children.
 * A parent whose every child was filtered away and which has no destination
 * of its own is dropped too, so the sidebar never renders an empty group.
 */
export function visibleNav(
  items: readonly NavItem[],
  actor: Actor,
  flags: FeatureFlagSnapshot,
): readonly NavItem[] {
  const visible: NavItem[] = [];

  for (const item of items) {
    if (item.flag !== undefined && !flagAllows(item.flag, actor, flags)) {
      continue;
    }
    if (item.action !== undefined && !can(actor, item.action, navResource(item.action, actor))) {
      continue;
    }

    if (item.children === undefined) {
      visible.push(item);
      continue;
    }

    const children = visibleNav(item.children, actor, flags);
    if (children.length === 0 && item.segment === "") continue;
    visible.push({ ...item, children });
  }

  return visible;
}
"use client";

/**
 * Role-aware sidebar: every item is filtered through `can()` and its flag.
 *
 * Must call (do not reimplement): can, isEnabled
 */
import Link from "next/link";
import { SETTINGS_NAV, SIDEBAR_NAV, visibleNav, type NavItem } from "@/config/nav";
import { cn } from "@/lib/cn";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { orgPath, projectPath } from "@/lib/url";
import { orgFlagContext } from "@/hooks/flag-context";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { OrgSwitcher } from "./org-switcher";

export type AppSidebarProps = {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
  projects: readonly Project[];
  pathname: string;
  /** Orgs offered by the switcher; defaults to just the current one. */
  organizations?: readonly Organization[];
};

/** True when `pathname` is the item's route or lives beneath it. */
export function isActiveSegment(pathname: string, href: string): boolean {
  return pathname === href || pathname.startsWith(`${href}/`);
}

export function AppSidebar(props: AppSidebarProps): ReactElement | null {
  const { org, actor, flags, projects, pathname, organizations } = props;

  // The nav tree declares the permission and flag each item needs; `visibleNav`
  // applies both. Nothing here branches on `actor.role`.
  const context = orgFlagContext(org, actor);
  const primary = visibleNav(SIDEBAR_NAV, actor, flags);
  const settings = visibleNav(SETTINGS_NAV, actor, flags);

  // The project shortcut list is its own gate: reading projects at all, and
  // the public-projects flag for the "shared" affordance.
  const mayReadProjects = can(
    actor,
    "project:read",
    organizationResource(org.id),
  );
  const publicProjectsOn =
    flags.public_projects === true || isEnabled("public_projects", context);

  function renderItem(item: NavItem): ReactElement {
    const href = orgPath(org.slug, item.segment);
    return (
      <li key={item.key}>
        <Link
          href={href}
          className={cn(
            "block rounded px-2 py-1 text-sm",
            isActiveSegment(pathname, href)
              ? "bg-neutral-200 font-medium"
              : "hover:bg-neutral-100",
          )}
        >
          {item.label}
        </Link>
        {item.children !== undefined && item.children.length > 0 ? (
          <ul className="ml-3 mt-0.5 space-y-0.5">
            {item.children.map(renderItem)}
          </ul>
        ) : null}
      </li>
    );
  }

  return (
    <nav className="app-sidebar flex w-56 shrink-0 flex-col gap-4 border-r p-3">
      <OrgSwitcher
        organizations={organizations ?? [org]}
        currentSlug={org.slug}
      />

      <ul className="space-y-0.5">{primary.map(renderItem)}</ul>

      {mayReadProjects && projects.length > 0 ? (
        <section>
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Projects
          </h2>
          <ul className="mt-1 space-y-0.5">
            {projects.map((project) => {
              const href = projectPath(org.slug, project.slug);
              return (
                <li key={project.id}>
                  <Link
                    href={href}
                    className={cn(
                      "flex items-center justify-between rounded px-2 py-1 text-sm",
                      isActiveSegment(pathname, href)
                        ? "bg-neutral-200 font-medium"
                        : "hover:bg-neutral-100",
                    )}
                  >
                    <span className="truncate">{project.name}</span>
                    {publicProjectsOn && project.visibility === "public" ? (
                      <span className="text-xs text-neutral-500">public</span>
                    ) : null}
                  </Link>
                </li>
              );
            })}
          </ul>
        </section>
      ) : null}

      {settings.length > 0 ? (
        <section className="mt-auto">
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Settings
          </h2>
          <ul className="mt-1 space-y-0.5">{settings.map(renderItem)}</ul>
        </section>
      ) : null}
    </nav>
  );
}
/**
 * Builds every internal href so route shapes live in one place. When the App
 * Router directory moves, this module changes and nothing else does — no
 * component or email template concatenates a path by hand.
 */

function encodeSegment(segment: string): string {
  return encodeURIComponent(segment);
}

function join(parts: readonly string[]): string {
  const cleaned = parts.filter((part) => part !== "" && part !== undefined);
  return `/${cleaned.join("/")}`;
}

/** `/acme` or `/acme/issues/…` — the dashboard root for one organization. */
export function orgPath(orgSlug: string, ...segments: readonly string[]): string {
  return join([encodeSegment(orgSlug), ...segments.map(encodeSegment)]);
}

export function projectPath(
  orgSlug: string,
  projectSlug: string,
  ...segments: readonly string[]
): string {
  return orgPath(orgSlug, "projects", projectSlug, ...segments);
}

export function issuePath(
  orgSlug: string,
  projectSlug: string,
  issueNumber: number,
): string {
  return projectPath(orgSlug, projectSlug, "issues", String(issueNumber));
}

export function settingsPath(orgSlug: string, section?: string): string {
  return section === undefined
    ? orgPath(orgSlug, "settings")
    : orgPath(orgSlug, "settings", section);
}

/**
 * Appends query parameters, dropping `undefined` entries so callers can pass
 * an optional filter straight through. Existing parameters on `path` are kept.
 */
export function withSearchParams(
  path: string,
  params: Readonly<Record<string, string | number | undefined>>,
): string {
  const [base, existing = ""] = path.split("?", 2);
  const search = new URLSearchParams(existing);

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined) {
      search.delete(key);
      continue;
    }
    search.set(key, String(value));
  }

  const query = search.toString();
  return query === "" ? (base ?? path) : `${base}?${query}`;
}
/** `visibleNav` filters by permission and by flag. */
import { describe, expect, it } from "vitest";
import { SETTINGS_NAV, SIDEBAR_NAV, visibleNav } from "@/config/nav";
import { snapshotFlags } from "@/lib/feature-flags";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { PlanId } from "@/types/billing";
import type { Role } from "@/types/member";
import { ALICE, ORG_A, makeActor } from "../helpers/factories";

function flagsFor(plan: PlanId, role: Role): FeatureFlagSnapshot {
  return snapshotFlags({ orgId: ORG_A, userId: ALICE, plan, role });
}

function keysOf(items: readonly { key: string }[]): readonly string[] {
  return items.map((item) => item.key);
}

describe("config/nav", () => {
  it("declares a permission for every nav entry", () => {
    for (const item of [...SIDEBAR_NAV, ...SETTINGS_NAV]) {
      expect(item.action, item.key).toBeDefined();
      expect(item.key).not.toBe("");
    }
  });

  it("shows an owner on an enterprise plan the full sidebar", () => {
    const visible = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("enterprise", "owner"),
    );
    expect(keysOf(visible)).toEqual(keysOf(SIDEBAR_NAV));
  });

  it("hides the activity feed from a viewer, who lacks activity:read", () => {
    const visible = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "viewer" }),
      flagsFor("enterprise", "viewer"),
    );
    expect(keysOf(visible)).not.toContain("activity");
    expect(keysOf(visible)).toContain("overview");
  });

  it("hides a flagged entry when the plan does not include the flag", () => {
    const free = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("free", "owner"),
    );
    expect(keysOf(free)).not.toContain("activity");

    const growth = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("growth", "owner"),
    );
    expect(keysOf(growth)).toContain("activity");
  });

  it("filters children independently of the parent", () => {
    const issues = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("free", "owner"),
    ).find((item) => item.key === "issues");

    expect(issues).toBeDefined();
    expect(keysOf(issues?.children ?? [])).toEqual(["issues.assigned"]);
  });

  it("keeps the board and advanced search once the plan includes them", () => {
    const issues = visibleNav(
      SIDEBAR_NAV,
      makeActor({ role: "owner" }),
      flagsFor("enterprise", "owner"),
    ).find((item) => item.key === "issues");

    expect(keysOf(issues?.children ?? [])).toEqual([
      "issues.assigned",
      "issues.board",
      "issues.search",
    ]);
  });

  it("shows an admin every settings page except billing", () => {
    const visible = visibleNav(
      SETTINGS_NAV,
      makeActor({ role: "admin" }),
      flagsFor("enterprise", "admin"),
    );
    expect(keysOf(visible)).toContain("settings.flags");
    expect(keysOf(visible)).not.toContain("settings.billing");
  });

  it("shows billing to an owner", () => {
    const visible = visibleNav(
      SETTINGS_NAV,
      makeActor({ role: "owner" }),
      flagsFor("enterprise", "owner"),
    );
    expect(keysOf(visible)).toContain("settings.billing");
  });

  it("hides webhooks and export on a plan without those flags", () => {
    const visible = visibleNav(
      SETTINGS_NAV,
      makeActor({ role: "owner" }),
      flagsFor("free", "owner"),
    );
    expect(keysOf(visible)).not.toContain("settings.webhooks");
    expect(keysOf(visible)).not.toContain("settings.export");
  });

  it("never mutates the source tree", () => {
    const before = JSON.stringify(SIDEBAR_NAV);
    visibleNav(SIDEBAR_NAV, makeActor({ role: "viewer" }), flagsFor("free", "viewer"));
    expect(JSON.stringify(SIDEBAR_NAV)).toBe(before);
  });
